class Solution { public int[] movesToStamp(String stamp,String target){char[] text=target.toCharArray();boolean[] done=new boolean[target.length()-stamp.length()+1];List<Integer> moves=new ArrayList<>();int erased=0;while(erased<text.length){boolean changed=false;for(int start=0;start<done.length;start++)if(!done[start]&&canErase(text,stamp,start)){int added=erase(text,start,stamp.length());if(added>0){erased+=added;changed=true;done[start]=true;moves.add(start);}}if(!changed)return new int[0];}Collections.reverse(moves);return moves.stream().mapToInt(Integer::intValue).toArray();}private boolean canErase(char[] text,String stamp,int start){boolean fresh=false;for(int i=0;i<stamp.length();i++)if(text[start+i]!='*'){if(text[start+i]!=stamp.charAt(i))return false;fresh=true;}return fresh;}private int erase(char[] text,int start,int length){int count=0;for(int i=0;i<length;i++)if(text[start+i]!='*'){text[start+i]='*';count++;}return count;} }
